<?php

/**
 * This class has been auto-generated by the Doctrine ORM Framework
 */
class NomCategoriatraza extends BaseNomCategoriatraza

{
    function setUp()
    {
        $this->hasMany('HisTraza', array('local'   => 'idcategoriatraza','foreign' => 'idcategoriatraza'));
    }

    static public function selectAllcategoria()
    {
        $query = Doctrine_Query::create(HisTraza::getConn());
        return $query->select('c.idcategoriatraza, c.denominacion')
            ->from('NomCategoriatraza c')
            ->orderby('c.idcategoriatraza')
            ->execute()->toArray();
    }

    static public function selectCategorias($start, $limit)
    {
        $query = Doctrine_Query::create(HisTraza::getConn());
        return $query->select('t.idcategoriatraza, t.denominacion')
            ->from('NomCategoriatraza t')
            ->limit($limit)
            ->offset($start)
            ->execute()->toArray();
    }

    static public function eliminarCategoria($categoria)
    {
        $query = Doctrine_Query::create(HisTraza::getConn());
        $query->delete()
            ->from('NomCategoriatraza t')
            ->where("t.idcategoriatraza = $categoria")
            ->execute();
        return $categoria;
    }
}
